void SNA::zero_uarraytot(const Kokkos::TeamPolicy<>::member_type& team)
{
  {
    double* const ptr = uarraytot_r.data();
    Kokkos::parallel_for(Kokkos::ThreadVectorRange(team,uarraytot_r.span()),
        [&] (const int& i) {
      ptr[i] = 0.0;
    });
  }
  {
    double* const ptr = uarraytot_i.data();
    Kokkos::parallel_for(Kokkos::ThreadVectorRange(team,uarraytot_r.span()),
